payload.cmd:
echo "=== record-graph decisions ===" && tail -5 .sofar/initiatives/record-graph/decisions.md && echo && echo "=== speed-2 decisions (tail) ===" && tail -3 .sofar/initiatives/speed-2/decisions.md && echo && echo "=== speed-2 events since writeback ===" && tail -12 .sofar/initiatives/speed-2/events.jsonl | python3 -c "import sys,json
for l in sys.stdin:
    e=json.loads(l); print(e['id'][:10], e['type'], str(e.get('payload',''))[:80], '| session:', str(e.get('session'))[:12])"

git diff --stat .sofar/initiatives/record-integrity/ && echo "=== events added ===" && git diff .sofar/initiatives/record-integrity/events.jsonl | grep "^+" | grep -v "^+++" | python3 -c "import sys,json
for l in sys.stdin:
    try:
        e=json.loads(l[1:]); print(e['id'][:12], e['type'], str(e.get('payload',''))[:100])
    except Exception as x: print('RAW:', l[:120].rstrip())"

git diff .sofar/initiatives/record-integrity/events.jsonl | grep '"type":"session_ended"' | python3 -c "import sys,json
for l in sys.stdin:
    e=json.loads(l[1:]); p=e['payload']; print('SUMMARY:', p['summary']); print(); print('NEXT:', p['next_action'])"
